","observer_contract":"# Final-post marker monitor contract v1

Use the unchanged public DUT pins in specification.md and the supplied module header.
The passive monitor additionally observes readonly trace_done:0 at every pre sample
and all post samples except the final post sample, where it is1. No extra rising
edge follows this marker. Enable finite-end checks combinationally from trace_done
and private state already updated by the final edge. The marker is evaluator
metadata, not a DUT input, truth label, reset or stimulus modification.

Development evaluations require drained=true,min_tail32; final evaluations use
drained=true,min_tail128. Definite failures and unknowns retain their independent
reference meanings; a short tail is never automatically accepted. A presented
valid safety failure is distinct from end-only response/input completion failure.
Independent reference inputs remain exactly the original six inputs/nine outputs;
the marker does not modify the Claude reference function or DUT specification.

Six active/ok slots,body<=16000UTF8bytes,state<=8192bits; readonly public pins,
posedge clk only, no hierarchy/files/assumptions/system calls. Short formal safety
projection explicitly sets trace_done=0 and cannot prove finite completion.
","previous_candidate":{"body":"reg seen = 0;
reg reset_post = 0;
reg [5:0] failed = 0;
reg [8:0] bytes_q [0:255];
reg [33:0] hdr_q [0:63];
reg [15:0] bw = 0, br = 0, hw = 0, hr = 0;
reg [4:0] in_len = 0;
reg mh = 0, hh = 0;
reg [8:0] saved_m = 0;
reg [33:0] saved_h = 0;
reg [5:0] live;
wire [15:0] bn = bw-br;
wire [15:0] hn = hw-hr;
wire [33:0] hp = {h_pad,h_truncate,h_length,h_original_length};
integer k;
integer add_b;
integer length_now;
integer out_length;

always @* begin
    live = 6'b111111;
    if (seen) begin
        // A presentation requires an already accepted prefix, even when blocked.
        if (m_valid !== 1'b0 && m_valid !== 1'b1) live[0] = 0;
        if (m_valid === 1'b1) begin
            if (bn == 0 || bn > 256) live[0] = 0;
            else if (({m_last,m_data} == bytes_q[br[7:0]]) !== 1'b1)
                live[0] = 0;
        end
        if (h_valid !== 1'b0 && h_valid !== 1'b1) live[1] = 0;
        if (h_valid === 1'b1) begin
            if (hn == 0 || hn > 64) live[1] = 0;
            else if ((hp == hdr_q[hr[5:0]]) !== 1'b1) live[1] = 0;
        end
        if (rst === 1'b0) begin
            if (mh && ((m_valid === 1'b1) &&
                (({m_last,m_data} == saved_m) === 1'b1)) !== 1'b1)
                live[2] = 0;
            if (hh && ((h_valid === 1'b1) &&
                ((hp == saved_h) === 1'b1)) !== 1'b1)
                live[2] = 0;
        end
        if (reset_post) begin
            if (m_valid !== 1'b0 || h_valid !== 1'b0) live[3] = 0;
        end
    end
    // This check is deliberately combinational: no edge follows trace_done.
    if (trace_done === 1'b1) begin
        if (bn != 0 || hn != 0 || in_len != 0 ||
            s_valid !== 1'b0 || m_valid !== 1'b0 || h_valid !== 1'b0)
            live[5] = 0;
    end
end

assign active = {trace_done === 1'b1,seen,seen,seen,seen,seen};
assign ok = live & ~failed;

always @(posedge clk) begin
    seen <= 1;
    failed <= failed | ~live;
    reset_post <= (rst === 1'b1);
    if (rst === 1'b1) begin
        bw <= 0; br <= 0; hw <= 0; hr <= 0;
        in_len <= 0;
        mh <= 0; hh <= 0;
    end else if (rst === 1'b0) begin
        mh <= (m_valid === 1'b1 && m_ready !== 1'b1);
        hh <= (h_valid === 1'b1 && h_ready !== 1'b1);
        saved_m <= {m_last,m_data};
        saved_h <= hp;
        if (m_valid === 1'b1 && m_ready === 1'b1 && bn != 0)
            br <= br+1'b1;
        if (h_valid === 1'b1 && h_ready === 1'b1 && hn != 0)
            hr <= hr+1'b1;
        if (s_valid === 1'b1 && s_ready === 1'b1) begin
            length_now = in_len+1;
            add_b = 0;
            if (length_now <= 8) begin
                if (bn < 253) begin
                    bytes_q[bw[7:0]] <= {
                        (length_now == 8 || (s_last === 1'b1 && length_now >= 4)),s_data};
                    add_b = 1;
                    if (s_last === 1'b1 && length_now < 4) begin
                        for (k=1;k<4;k=k+1) begin
                            if (k <= 4-length_now)
                                bytes_q[(bw+k)&255] <= {(k == 4-length_now),8'd0};
                        end
                        add_b = 5-length_now;
                    end
                    bw <= bw+add_b;
                end else failed[4] <= 1;
            end
            if (s_last !== 1'b0 && s_last !== 1'b1) failed[4] <= 1;
            if ((^s_data) !== 1'b0 && (^s_data) !== 1'b1) failed[4] <= 1;
            if (length_now > 12) failed[4] <= 1;
            if (s_last === 1'b1) begin
                in_len <= 0;
                out_length = length_now < 4 ? 4 : (length_now > 8 ? 8 : length_now);
                if (hn < 64) begin
                    hdr_q[hw[5:0]] <= { (length_now < 4), (length_now > 8),
                        16'(out_length),16'(length_now)};
                    hw <= hw+1'b1;
                end else failed[4] <= 1;
            end else if (in_len < 31) in_len <= in_len+1'b1;
        end
        if (s_valid !== 1'b0 && s_valid !== 1'b1) failed[4] <= 1;
        if (s_valid === 1'b1 && s_ready !== 1'b0 && s_ready !== 1'b1)
            failed[4] <= 1;
        if (m_valid === 1'b1 && m_ready !== 1'b0 && m_ready !== 1'b1)
            failed[4] <= 1;
        if (h_valid === 1'b1 && h_ready !== 1'b0 && h_ready !== 1'b1)
            failed[4] <= 1;
    end else failed[4] <= 1;
end
